+)
+
+func main() {
+	// Test sum with empty node set
+	fmt.Println("Testing sum with empty expression:")
+	expr, err := xpath.Compile("sum(/nonexistent)")
+	if err != nil {
+		fmt.Printf("Error compiling expression: %v\n", err)
+		return
+	}
+	
+	// Create a simple node navigator for testing
+	nav := &simpleNavigator{}
+	result := expr.Evaluate(nav)
+	fmt.Printf("Result: %v (type: %T)\n", result, result)
+	
+	// Test sum with NaN values
+	fmt.Println("\nTesting sum behavior with NaN would require modifying the source")
+}
+
+// Simple implementation of NodeNavigator for testing
+type simpleNavigator struct{}
+
+func (n *simpleNavigator) NodeType() xpath.NodeType { return xpath.RootNode }
+func (n *simpleNavigator) LocalName() string { return "" }
+func (n *simpleNavigator) Prefix() string { return "" }
+func (n *simpleNavigator) Value() string { return "" }
+func (n *simpleNavigator) Copy() xpath.NodeNavigator { return n }
