+func (n *simpleNavigator) MoveToNext() bool { return false }
+func (n *simpleNavigator) MoveToChild() bool { return false }
+func (n *simpleNavigator) MoveToFirst() bool { return false }
+func (n *simpleNavigator) MoveToPrevious() bool { return false }
+func (n *simpleNavigator) MoveTo(other xpath.NodeNavigator) { }
+func (n *simpleNavigator) MoveToID(string) bool { return false }
